export default "<template>\n  <div>\n    <raw-loader v-show=\"level == 9\" :mytxt=\"require('!raw-loader!./Icons2.vue').default\"\n      :btnText=\"`Code Icons2 [${level}]`\"></raw-loader>\n    <h4>This is Tpl</h4>\n    level : {{ level }}\n\n    <ul>\n      <li v-for=\"x in ds\" :key=\"x.id\" class=\"my-1\">\n        {{ x.label }} - {{ x.id }}\n        <button @click=\"copyIcon(x.label)\">copy</button>\n      </li>\n    </ul>\n\n  </div>\n</template>\n\n<script>\nexport default {\n  name: 'HomeView',\n  components: {\n  },\n  computed: {\n    user() {\n      return JSON.parse(localStorage.getItem('user') || '{}')\n    },\n    level() {\n      return this.user.level || 0\n    }\n  },\n  data() {\n    return {\n\n      ds: [\n        { id: 'Home', label: '🏠' },\n        { id: 'Dashboard', label: '📊' },\n        { id: 'Analytics', label: '📈' },\n        { id: 'Admin', label: '🖥️' },\n        { id: 'Settings', label: '⚙️' },\n\n        { id: 'Product', label: '📦' },\n        { id: 'Cart', label: '🛒' },\n        { id: 'Tag', label: '🏷️' },\n        { id: 'List', label: '📋' },\n        { id: 'Folder', label: '📁' },\n\n        { id: 'User', label: '👤' },\n        { id: 'Users', label: '👥' },\n        { id: 'Login', label: '🔐' },\n        { id: 'Key', label: '🔑' },\n        { id: 'Logout', label: '🚪' },\n\n        { id: 'Phone', label: '📞' },\n        { id: 'Mail', label: '✉️' },\n        { id: 'Chat', label: '💬' },\n        { id: 'Email', label: '📧' },\n\n        { id: 'Money', label: '💰' },\n        { id: 'Card', label: '💳' },\n        { id: 'Loss', label: '📉' },\n        { id: 'Profit', label: '📈' },\n        { id: 'Invoice', label: '🧾' },\n\n        { id: 'Tools', label: '🛠️' },\n        { id: 'Fix', label: '🔧' },\n        { id: 'Test', label: '🧪' },\n        { id: 'Deploy', label: '🚀' }\n      ],\n\n\n    }\n  },\n\nmethods: {\n  async copyIcon(icon) {\n    try {\n      await navigator.clipboard.writeText(icon)\n      console.log('Copied:', icon)\n      // nếu có toast thì show ở đây\n    } catch (err) {\n      console.error('Copy failed', err)\n\n      // fallback cho browser cũ\n      const textarea = document.createElement('textarea')\n      textarea.value = icon\n      document.body.appendChild(textarea)\n      textarea.select()\n      document.execCommand('copy')\n      document.body.removeChild(textarea)\n    }\n  }\n}\n\n\n\n\n\n\n\n\n}\n</script>\n";